                transition: 'all 0.2s'
              }}
            >
              Cut Body
            </button>
          </div>

          {/* 显示切割面开关 */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <input
              type="checkbox"
              id="showPlane"
