              }}
              title="Toggle white wireframe overlay in Cut Body mode"
            >
              {showCutBodyWireframe ? 'Hide Cut Body Wireframe' : 'Show Cut Body Wireframe'}
            </button>
          )}

          {/* 多刀切割控制 */}
