              <input
                type="number"
                min="0"
                value={pendingCutCount}
                onChange={(e) => {
                  const value = Number(e.target.value)
                  setPendingCutCount(Math.max(0, Number.isFinite(value) ? value : 0))
                }}
                style={{
                  width: '90px',
                  padding: '8px',
                  background: '#2a2a2a',
                  border: '1px solid #444',
                  borderRadius: '4px',
                  color: 'white',
                  fontSize: '14px'
                }}
              />
            </div>

            <button
              onClick={() => setAppliedCutCount(clampedPendingCutCount)}
              style={{
                padding: '8px 14px',
                background: appliedCutCount > 0 ? '#00796b' : '#2a2a2a',
                border: appliedCutCount > 0 ? '2px solid #26a69a' : '1px solid #444',
                borderRadius: '6px',
                color: appliedCutCount > 0 ? 'white' : '#aaa',
                fontSize: '13px',
                cursor: 'pointer'
              }}
              title="Apply N sequential cuts on the remaining body"
            >
              Apply N Cuts
            </button>

            {appliedCutCount > 0 && (
              <button
                onClick={() => setAppliedCutCount(0)}
                style={{
                  padding: '8px 14px',
                  background: '#f44336',
                  border: '2px solid #f44336',
                  borderRadius: '6px',
                  color: 'white',
                  fontSize: '13px',
                  fontWeight: 'bold',
                  cursor: 'pointer',
                  transition: 'all 0.2s'
                }}
                onMouseOver={(e) => {
                  e.currentTarget.style.background = '#d32f2f'
                  e.currentTarget.style.borderColor = '#d32f2f'
                }}
                onMouseOut={(e) => {
                  e.currentTarget.style.background = '#f44336'
                  e.currentTarget.style.borderColor = '#f44336'
                }}
                title="Cancel multi-cut and return to single cut mode"
              >
                ✕ Cancel N Cuts
              </button>
            )}
          </div>

          {/* 重置按钮 */}
          <button
            onClick={() => {
              setCutDepth(0)
              setCutAngle(0)
              setShowCutPlane(true)
              setShowCutBodyWireframe(false)
              setPendingCutCount(3)
              setAppliedCutCount(0)
            }}
            style={{
              padding: '10px 20px',
              background: '#ff6b6b',
              border: 'none',
              borderRadius: '6px',
              color: 'white',
              fontSize: '14px',
              fontWeight: 'bold',
              cursor: 'pointer',
              transition: 'background 0.2s'
            }}
            onMouseOver={(e) => e.currentTarget.style.background = '#ff5252'}
            onMouseOut={(e) => e.currentTarget.style.background = '#ff6b6b'}
          >
            Reset
          </button>
        </div>

        {/* 提示信息 */}
        <div style={{ marginTop: '15px', fontSize: '12px', color: '#888' }}>
           Hint: 
          • Cut Face: Shows only the cross-section (precise boundary matching model)
          • Cut Body: Shows the removed part as a red solid
          • Apply N Cuts: Splits the removed range into N sequential cuts; each cut only acts on the remaining body
          • Cancel N Cuts: Remove all applied cuts and return to single cut mode
          • The region between two neighboring knives is rendered with a different color in Cut Body mode
          • Drag sliders or enter values to adjust cutting position and angle
          • Mouse: rotate, zoom, and pan to view the model
        </div>
      </div>
    </div>
  )
}

import React, { useMemo } from 'react'
import * as THREE from 'three'
import { useGLTF } from '@react-three/drei'
import { GLTF } from 'three-stdlib'

const MULTI_CUT_COLORS = [
  '#e63946',
  '#118ab2',
  '#ffd166',
  '#06d6a0',
  '#8338ec',
  '#fb8500',
  '#3a86ff',
  '#ef476f',
  '#8ac926',
  '#ff006e',
  '#ffbe0b',
  '#2ec4b6',
]

function getProjectionRange(box: THREE.Box3, normal: THREE.Vector3) {
  const corners = [
    new THREE.Vector3(box.min.x, box.min.y, box.min.z),
    new THREE.Vector3(box.max.x, box.min.y, box.min.z),
    new THREE.Vector3(box.min.x, box.max.y, box.min.z),
    new THREE.Vector3(box.max.x, box.max.y, box.min.z),
    new THREE.Vector3(box.min.x, box.min.y, box.max.z),
    new THREE.Vector3(box.max.x, box.min.y, box.max.z),
    new THREE.Vector3(box.min.x, box.max.y, box.max.z),
    new THREE.Vector3(box.max.x, box.max.y, box.max.z),
  ]

  let min = Infinity
  let max = -Infinity

  corners.forEach((corner) => {
    const dist = corner.dot(normal)
    min = Math.min(min, dist)
    max = Math.max(max, dist)
  })

  return { min, max }
}

function createForwardPlane(normal: THREE.Vector3, distance: number) {
  return new THREE.Plane(normal.clone(), -distance)
}

function createReversePlane(normal: THREE.Vector3, distance: number) {
  return new THREE.Plane(normal.clone().negate(), distance)
}

type SequentialCutLayer = {
  index: number
  startDistance: number
  endDistance: number
  color: string
  clippingPlanes: THREE.Plane[]
}

type GLTFResult = GLTF & {
  nodes: {
    HZ3: THREE.Mesh
  }
  materials: {
    HZ3_Material_u1_v1: THREE.MeshPhysicalMaterial
  }
}

interface PreciseDualModeModelProps {
  cutDepth: number
  cutAngle: number
  showCutPlane?: boolean
  mode: 'cutBody' | 'cutFace'
  capColor?: string
  showCutBodyWireframe?: boolean
  multiCutCount?: number
}

export function PreciseDualModeModel({ 
  cutDepth, 
  cutAngle, 
  showCutPlane = true,
  mode = 'cutFace',
  capColor = '#ff6b6b',
  showCutBodyWireframe = false,
  multiCutCount = 0
}: PreciseDualModeModelProps) {
  const { nodes, materials } = useGLTF('/Hohenzollern_Castle_optimized.glb') as GLTFResult

  // 计算模型的包围盒
  const modelBounds = useMemo(() => {
    if (!nodes.HZ3.geometry) return null

    const geometry = nodes.HZ3.geometry
    geometry.computeBoundingBox()
    const box = geometry.boundingBox

    if (!box) return null

    return { box }
  }, [nodes.HZ3.geometry])

  const cutNormal = useMemo(() => {
    const angleRad = (cutAngle * Math.PI) / 180
    return new THREE.Vector3(
      Math.cos(angleRad),
      0,
      Math.sin(angleRad)
    ).normalize()
  }, [cutAngle])

  const projectionRange = useMemo(() => {
    if (!modelBounds) return null
    return getProjectionRange(modelBounds.box, cutNormal)
  }, [modelBounds, cutNormal])

  const effectiveMultiCutCount = Math.max(0, Math.min(12, Math.floor(multiCutCount)))

  // 裁剪平面计算
  const clippingPlane = useMemo(() => {
    if (cutDepth < 0 || cutDepth > 100 || !projectionRange) return null

    // 深度为 0 时不切割，返回 null
    if (cutDepth === 0) return null

    // ⚠️ 关键：深度为 100 时，将平面移到模型之外，确保完全不显示
    if (cutDepth === 100) {
      const planeDist = projectionRange.max + 0.01
      const constant = -planeDist

      console.log('✂️ 裁剪平面 (100%):', { 
        mode,
        cutDepth,
        normal: cutNormal.toArray(), 
        constant,
        description: '完全切掉'
      })

      return new THREE.Plane(cutNormal.clone(), constant)
    }

    const range = projectionRange.max - projectionRange.min
    const planeDist = projectionRange.min + (range * cutDepth / 100)
    const constant = -planeDist

    console.log('✂️ 裁剪平面:', { 
      mode,
      cutDepth, 
      cutAngle,
      normal: cutNormal.toArray(), 
      constant,
      planeDist,
      minDist: projectionRange.min,
      maxDist: projectionRange.max,
      description: cutDepth === 0 ? '不切割' : cutDepth === 100 ? '全切' : `切掉${cutDepth}%`
    })

    return new THREE.Plane(cutNormal.clone(), constant)
  }, [cutDepth, cutAngle, projectionRange, cutNormal, mode])

  const sequentialCutLayers = useMemo(() => {
    if (
      mode !== 'cutBody' ||
      !projectionRange ||
      cutDepth >= 100 ||
      effectiveMultiCutCount <= 0
    ) {
      return [] as SequentialCutLayer[]
    }

    // clippingPlane 保留 dot(normal,p) >= planeDist（高值侧 = 剩余体）
    // cutDepth=0: 剩余体 = 完整模型 [projectionRange.min, projectionRange.max]
    // cutDepth>0: 剩余体 = [planeDist, projectionRange.max]，planeDist = -clippingPlane.constant
    const remainingMin = cutDepth === 0
      ? projectionRange.min
      : (clippingPlane ? -clippingPlane.constant : projectionRange.min)
    const remainingMax = projectionRange.max
    const remainingSpan = remainingMax - remainingMin

    if (remainingSpan <= 0.0001) return [] as SequentialCutLayer[]

    // N 刀对应 N 个彩色分层，剩余最后一段由主材质渲染
    const step = remainingSpan / (effectiveMultiCutCount + 1)
    const layers: SequentialCutLayer[] = []
    const epsilon = Math.max(step * 0.001, 1e-4)

    for (let index = 0; index < effectiveMultiCutCount; index += 1) {
      // index=0 紧贴 Cut Body 切面，依次向内（高值侧）
      const startDistance = remainingMin + step * index
      const endDistance = remainingMin + step * (index + 1)

      // 仅在每层末端留极小间隙，避免与下一层或尾段主材质共面。
      const adjustedStart = startDistance
      const adjustedEnd = endDistance - epsilon

      if (adjustedEnd - adjustedStart <= 1e-5) {
        continue
      }

      layers.push({
        index,
        startDistance: adjustedStart,
        endDistance: adjustedEnd,
        color: MULTI_CUT_COLORS[index % MULTI_CUT_COLORS.length],
        // createForwardPlane(d): 保留 dot >= d
        // createReversePlane(d): 保留 dot <= d
        // 两者同时作用：保留 startDist <= dot <= endDist
        clippingPlanes: [
          createForwardPlane(cutNormal, adjustedStart),
          createReversePlane(cutNormal, adjustedEnd),
        ],
      })
    }

    console.log(' 多刀切割层:', {
      totalLayers: layers.length,
      expectedLayers: effectiveMultiCutCount,
      step,
      remainingMin,
      remainingMax,
      layers: layers.map(l => ({
        index: l.index,
        start: l.startDistance.toFixed(2),
        end: l.endDistance.toFixed(2)
      }))
    })

    return layers
  }, [mode, projectionRange, clippingPlane, cutDepth, effectiveMultiCutCount, cutNormal])

  const isMultiCutActive = mode === 'cutBody' && sequentialCutLayers.length > 0 && cutDepth < 100

  // 主材质 - 始终应用裁剪
  const mainMaterial = useMemo(() => {
    if (!materials.HZ3_Material_u1_v1) return null

    const material = materials.HZ3_Material_u1_v1.clone()

    const activePlane = isMultiCutActive
      ? createForwardPlane(cutNormal, sequentialCutLayers[sequentialCutLayers.length - 1].endDistance)
      : clippingPlane

    if (activePlane) {
      material.clippingPlanes = [activePlane]
      material.clipShadows = true
      material.needsUpdate = true
    }

    return material
  }, [materials.HZ3_Material_u1_v1, clippingPlane, isMultiCutActive, cutNormal, sequentialCutLayers])

  const showCutSection = showCutPlane && cutDepth > 0 && cutDepth < 100

  // Cut Face 模式：创建与裁剪面重合的大平面，最终由 stencil 裁成精确轮廓
  const capGeometry = useMemo(() => {
    if (!clippingPlane || mode !== 'cutFace' || !modelBounds) return null

    const box = modelBounds.box
    const diagonal = Math.sqrt(
      Math.pow(box.max.x - box.min.x, 2) +
      Math.pow(box.max.y - box.min.y, 2) +
      Math.pow(box.max.z - box.min.z, 2)
    )

    const geometry = new THREE.PlaneGeometry(diagonal * 2, diagonal * 2, 1, 1)

    const quaternion = new THREE.Quaternion()
    quaternion.setFromUnitVectors(
      new THREE.Vector3(0, 0, 1),
      clippingPlane.normal
    )
    geometry.applyQuaternion(quaternion)

    const position = clippingPlane.normal.clone().multiplyScalar(-clippingPlane.constant)
    geometry.translate(position.x, position.y, position.z)

    return geometry
  }, [clippingPlane, mode, modelBounds])

  const capMaterial = useMemo(() => {
    if (!clippingPlane || mode !== 'cutFace') return null

    const material = new THREE.MeshBasicMaterial({
      color: capColor,
      side: THREE.DoubleSide,
      transparent: false,
      opacity: 1.0,
      depthWrite: true,
      depthTest: true,
      fog: false,
      stencilWrite: true,
      stencilRef: 0,
      stencilFunc: THREE.NotEqualStencilFunc,
      stencilFail: THREE.ReplaceStencilOp,
      stencilZFail: THREE.ReplaceStencilOp,
      stencilZPass: THREE.ReplaceStencilOp,
    })

    material.needsUpdate = true
    return material
  }, [clippingPlane, capColor, mode])

  // 用前/后面双通道写 stencil，得到切割截面的精确掩码
  const stencilBackMaterial = useMemo(() => {
    if (!clippingPlane || mode !== 'cutFace') return null

    const material = new THREE.MeshBasicMaterial({
      side: THREE.BackSide,
      clippingPlanes: [clippingPlane],
      colorWrite: false,
      depthWrite: false,
      depthTest: false,
      stencilWrite: true,
      stencilFunc: THREE.AlwaysStencilFunc,
      stencilFail: THREE.KeepStencilOp,
      stencilZFail: THREE.KeepStencilOp,
      stencilZPass: THREE.IncrementWrapStencilOp,
    })

    material.needsUpdate = true
    return material
  }, [clippingPlane, mode])

  const stencilFrontMaterial = useMemo(() => {
    if (!clippingPlane || mode !== 'cutFace') return null

    const material = new THREE.MeshBasicMaterial({
      side: THREE.FrontSide,
      clippingPlanes: [clippingPlane],
      colorWrite: false,
      depthWrite: false,
      depthTest: false,
      stencilWrite: true,
      stencilFunc: THREE.AlwaysStencilFunc,
      stencilFail: THREE.KeepStencilOp,
      stencilZFail: THREE.KeepStencilOp,
      stencilZPass: THREE.DecrementWrapStencilOp,
    })

    material.needsUpdate = true
    return material
  }, [clippingPlane, mode])



  // Cut Body 模式：保留原材质颜色，仅叠加轻微高亮特效
  const cutBodyMaterial = useMemo(() => {
    if (!clippingPlane || mode !== 'cutBody') return null

    const reversePlane = new THREE.Plane(
      clippingPlane.normal.clone().negate(),
      -clippingPlane.constant
    )

    const material = materials.HZ3_Material_u1_v1.clone()
    material.side = THREE.DoubleSide
    material.transparent = true
    material.opacity = 0.5 //Cut Body被切割区域颜色透明度（越大透明度越高）
    material.clippingPlanes = [reversePlane]
    material.clipShadows = true

    // 轻微冷色发光，保留原本纹理与颜色层次
    material.emissive = new THREE.Color('#6fb7ff')//Cut Body被切割区域颜色
    material.emissiveIntensity = 0.12
    material.clearcoat = 0.5
    material.clearcoatRoughness = 0.35

    material.needsUpdate = true

    console.log(' 切割体材质:', {
      type: material.type,
      color: '#' + material.color.getHexString(),
      opacity: material.opacity,
      transparent: material.transparent,
      clippingPlanes: 'reverse',
      note: '保留原材质并叠加轻微高亮'
    })

    return material
  }, [clippingPlane, mode, materials.HZ3_Material_u1_v1])

  // Cut Body 截面填充：使用原材质颜色的提亮版，避免纯红色块
  const cutBodyCapMaterial = useMemo(() => {
    if (!clippingPlane || mode !== 'cutBody') return null

    // 创建反向裁剪平面（只保留截面部分）
    const reversePlane = new THREE.Plane(
      clippingPlane.normal.clone().negate(),
      -clippingPlane.constant
    )

    const sectionColor = materials.HZ3_Material_u1_v1.color.clone().lerp(new THREE.Color('#ffffff'), 1)

    const material = new THREE.MeshStandardMaterial({
      color: sectionColor,
      emissive: sectionColor.clone(),
      emissiveIntensity: 0.2,
      side: THREE.DoubleSide,
      transparent: false,
      opacity: 1.0,
      roughness: 0.35,
      metalness: 0.15,
      depthWrite: true,
      depthTest: true,
      fog: false,
      clippingPlanes: [reversePlane],
      clipShadows: true,
    })

    material.needsUpdate = true

    console.log(' 切割体截面材质:', {
      type: material.type,
      color: '#' + material.color.getHexString(),
      clippingPlanes: 'reverse (single plane)',
      side: 'DoubleSide',
      note: '原色提亮的截面填充'
    })

    return material
  }, [clippingPlane, mode, materials.HZ3_Material_u1_v1])

  const sequentialCutMaterials = useMemo(() => {
    if (mode !== 'cutBody' || sequentialCutLayers.length === 0) return [] as THREE.MeshPhysicalMaterial[]

    return sequentialCutLayers.map((layer) => {
      const material = materials.HZ3_Material_u1_v1.clone()
      const layerColor = new THREE.Color(layer.color)

      material.color = layerColor.clone()
      material.emissive = layerColor.clone()
      material.emissiveIntensity = 0.28
      material.side = THREE.DoubleSide
      material.transparent = true
      material.opacity = 0.72
      material.clearcoat = 0.5
      material.clearcoatRoughness = 0.35
      material.clippingPlanes = layer.clippingPlanes
      // Three.js clipping with this plane pair uses clipIntersection=false to keep slab interval.
      material.clipIntersection = false
      material.clipShadows = true
      // depthWrite = false 消除 Z-fighting（同几何体多层叠加时无需写深度）
      material.depthWrite = false
      material.needsUpdate = true

      return material
    })
  }, [mode, sequentialCutLayers, materials.HZ3_Material_u1_v1])

  if (!mainMaterial) return null

  return (
    <group dispose={null}>
      {/* 主模型 */}
      <mesh
        geometry={nodes.HZ3.geometry}
        material={mainMaterial}
        castShadow
        receiveShadow
      />

      {/* 原始 Cut Body：蓝色透明层 + 白色截面填充，统一受 showCutSection 控制 */}
      {mode === 'cutBody' && cutBodyMaterial && cutBodyCapMaterial && showCutSection && (
        <>
          <mesh
            geometry={nodes.HZ3.geometry}
            material={cutBodyMaterial}
            renderOrder={1}
          />

          {showCutBodyWireframe && (
            <mesh
              geometry={nodes.HZ3.geometry}
              renderOrder={2}
            >
              <meshBasicMaterial
                color="#ffffff"
                wireframe={true}
                transparent={true}
                opacity={0.5}
                clippingPlanes={[new THREE.Plane(
                  clippingPlane!.normal.clone().negate(),
                  -clippingPlane!.constant
                )]}
              />
            </mesh>
          )}

          <mesh
            geometry={nodes.HZ3.geometry}
            material={cutBodyCapMaterial}
            renderOrder={showCutBodyWireframe ? 3 : 2}
          />
        </>
      )}

      {/* 在 Cut Body 剩余部分（或完整模型）上继续切 N 刀 */}
      {isMultiCutActive && (
        <>
          {sequentialCutLayers.map((layer, index) => (
            <mesh
              key={`sequential-cut-${layer.index}`}
              geometry={nodes.HZ3.geometry}
              material={sequentialCutMaterials[index]}
              renderOrder={10 + index * 2}
            />
          ))}

          {showCutBodyWireframe && sequentialCutLayers.map((layer) => (
            <mesh
              key={`sequential-cut-wireframe-${layer.index}`}
              geometry={nodes.HZ3.geometry}
              renderOrder={11 + layer.index * 2}
            >
              <meshBasicMaterial
                color={layer.color}
                wireframe={true}
                transparent={true}
                opacity={0.32}
                clippingPlanes={layer.clippingPlanes}
                clipIntersection={false}
              />
            </mesh>
          ))}

        </>
      )}

      {/* 模式2: Cut Face - stencil 精确匹配截面边界 */}
      {mode === 'cutFace' && stencilBackMaterial && showCutSection && (
        <mesh
          geometry={nodes.HZ3.geometry}
          material={stencilBackMaterial}
          renderOrder={1}
        />
      )}

      {mode === 'cutFace' && stencilFrontMaterial && showCutSection && (
        <mesh
          geometry={nodes.HZ3.geometry}
          material={stencilFrontMaterial}
          renderOrder={2}
        />
      )}

      {mode === 'cutFace' && capGeometry && capMaterial && clippingPlane && showCutSection && (
        <mesh
          geometry={capGeometry}
          material={capMaterial}
          renderOrder={3}
          onAfterRender={(renderer: THREE.WebGLRenderer) => {
            renderer.clearStencil()
          }}
        />
      )}
    </group>
  )
}

useGLTF.preload('/Hohenzollern_Castle_optimized.glb')

import React, { useMemo } from 'react'
import * as THREE from 'three'
import { useGLTF } from '@react-three/drei'
import { GLTF } from 'three-stdlib'

const MULTI_CUT_COLORS = [
  '#e63946',
  '#118ab2',
  '#ffd166',
  '#06d6a0',
  '#8338ec',
  '#fb8500',
  '#3a86ff',
  '#ef476f',
  '#8ac926',
  '#ff006e',
  '#ffbe0b',
  '#2ec4b6',
]

function getProjectionRange(box: THREE.Box3, normal: THREE.Vector3) {
  const corners = [
    new THREE.Vector3(box.min.x, box.min.y, box.min.z),
    new THREE.Vector3(box.max.x, box.min.y, box.min.z),
    new THREE.Vector3(box.min.x, box.max.y, box.min.z),
    new THREE.Vector3(box.max.x, box.max.y, box.min.z),
    new THREE.Vector3(box.min.x, box.min.y, box.max.z),
    new THREE.Vector3(box.max.x, box.min.y, box.max.z),
    new THREE.Vector3(box.min.x, box.max.y, box.max.z),
    new THREE.Vector3(box.max.x, box.max.y, box.max.z),
  ]

  let min = Infinity
  let max = -Infinity

  corners.forEach((corner) => {
    const dist = corner.dot(normal)
    min = Math.min(min, dist)
    max = Math.max(max, dist)
  })

  return { min, max }
}

function createForwardPlane(normal: THREE.Vector3, distance: number) {
  return new THREE.Plane(normal.clone(), -distance)
}

function createReversePlane(normal: THREE.Vector3, distance: number) {
  return new THREE.Plane(normal.clone().negate(), distance)
}

type SequentialCutLayer = {
  index: number
  startDistance: number
  endDistance: number
  color: string
  clippingPlanes: THREE.Plane[]
}

type GLTFResult = GLTF & {
  nodes: {
    HZ3: THREE.Mesh
  }
  materials: {
    HZ3_Material_u1_v1: THREE.MeshPhysicalMaterial
  }
}

interface PreciseDualModeModelProps {
  cutDepth: number
  cutAngle: number
  showCutPlane?: boolean
  mode: 'cutBody' | 'cutFace'
  capColor?: string
  showCutBodyWireframe?: boolean
  multiCutCount?: number
}

export function PreciseDualModeModel({ 
  cutDepth, 
  cutAngle, 
  showCutPlane = true,
  mode = 'cutFace',
  capColor = '#ff6b6b',
  showCutBodyWireframe = false,
  multiCutCount = 0
}: PreciseDualModeModelProps) {
  const { nodes, materials } = useGLTF('/Hohenzollern_Castle_optimized.glb') as GLTFResult

  // 计算模型的包围盒
  const modelBounds = useMemo(() => {
    if (!nodes.HZ3.geometry) return null

    const geometry = nodes.HZ3.geometry
    geometry.computeBoundingBox()
    const box = geometry.boundingBox

    if (!box) return null

    return { box }
  }, [nodes.HZ3.geometry])

  const cutNormal = useMemo(() => {
    const angleRad = (cutAngle * Math.PI) / 180
    return new THREE.Vector3(
      Math.cos(angleRad),
      0,
      Math.sin(angleRad)
    ).normalize()
  }, [cutAngle])

  const projectionRange = useMemo(() => {
    if (!modelBounds) return null
    return getProjectionRange(modelBounds.box, cutNormal)
  }, [modelBounds, cutNormal])

  const effectiveMultiCutCount = Math.max(
    0,
    Math.floor(Number.isFinite(multiCutCount) ? multiCutCount : 0)
  )

  // 裁剪平面计算
  const clippingPlane = useMemo(() => {
    if (cutDepth < 0 || cutDepth > 100 || !projectionRange) return null

    // 深度为 0 时不切割，返回 null
    if (cutDepth === 0) return null

    // ⚠️ 关键：深度为 100 时，将平面移到模型之外，确保完全不显示
    if (cutDepth === 100) {
      const planeDist = projectionRange.max + 0.01
      const constant = -planeDist

      console.log('✂️ 裁剪平面 (100%):', { 
        mode,
        cutDepth,
        normal: cutNormal.toArray(), 
        constant,
        description: '完全切掉'
      })

      return new THREE.Plane(cutNormal.clone(), constant)
    }

    const range = projectionRange.max - projectionRange.min
    const planeDist = projectionRange.min + (range * cutDepth / 100)
    const constant = -planeDist

    console.log('✂️ 裁剪平面:', { 
      mode,
      cutDepth, 
      cutAngle,
      normal: cutNormal.toArray(), 
      constant,
      planeDist,
      minDist: projectionRange.min,
      maxDist: projectionRange.max,
      description: cutDepth === 0 ? '不切割' : cutDepth === 100 ? '全切' : `切掉${cutDepth}%`
    })

    return new THREE.Plane(cutNormal.clone(), constant)
  }, [cutDepth, cutAngle, projectionRange, cutNormal, mode])

  const sequentialCutLayers = useMemo(() => {
    if (
      mode !== 'cutBody' ||
      !projectionRange ||
      cutDepth >= 100 ||
      effectiveMultiCutCount <= 0
    ) {
      return [] as SequentialCutLayer[]
    }

    // clippingPlane 保留 dot(normal,p) >= planeDist（高值侧 = 剩余体）
    // cutDepth=0: 剩余体 = 完整模型 [projectionRange.min, projectionRange.max]
    // cutDepth>0: 剩余体 = [planeDist, projectionRange.max]，planeDist = -clippingPlane.constant
    const remainingMin = cutDepth === 0
      ? projectionRange.min
      : (clippingPlane ? -clippingPlane.constant : projectionRange.min)
    const remainingMax = projectionRange.max
    const remainingSpan = remainingMax - remainingMin

    if (remainingSpan <= 0.0001) return [] as SequentialCutLayer[]

    // N 刀对应 N 个彩色分层，剩余最后一段由主材质渲染
    const step = remainingSpan / (effectiveMultiCutCount + 1)
    const layers: SequentialCutLayer[] = []
    // Keep a tiny dynamic gap to avoid coplanar flicker, but never let it swallow thin slices.
    const epsilon = Math.min(step * 0.25, Math.max(step * 0.001, 1e-7))

    for (let index = 0; index < effectiveMultiCutCount; index += 1) {
      // index=0 紧贴 Cut Body 切面，依次向内（高值侧）
      const startDistance = remainingMin + step * index
      const endDistance = remainingMin + step * (index + 1)

      // First layer is moved slightly inward to avoid coplanar overlap with the Cut Body split plane.
      const adjustedStart = index === 0 ? startDistance + epsilon : startDistance
      // 仅在每层末端留极小间隙，避免与下一层或尾段主材质共面。
      const adjustedEnd = endDistance - epsilon

      layers.push({
        index,
        startDistance: adjustedStart,
        endDistance: adjustedEnd,
        color: MULTI_CUT_COLORS[index % MULTI_CUT_COLORS.length],
        // createForwardPlane(d): 保留 dot >= d
        // createReversePlane(d): 保留 dot <= d
        // 两者同时作用：保留 startDist <= dot <= endDist
        clippingPlanes: [
          createForwardPlane(cutNormal, adjustedStart),
          createReversePlane(cutNormal, adjustedEnd),
        ],
      })
    }

    console.log(' 多刀切割层:', {
      totalLayers: layers.length,
      expectedLayers: effectiveMultiCutCount,
      step,
      epsilon,
      remainingMin,
      remainingMax,
      layers: layers.map(l => ({
        index: l.index,
        start: l.startDistance.toFixed(2),
        end: l.endDistance.toFixed(2)
      }))
    })

    return layers
  }, [mode, projectionRange, clippingPlane, cutDepth, effectiveMultiCutCount, cutNormal])

  const isMultiCutActive = mode === 'cutBody' && sequentialCutLayers.length > 0 && cutDepth < 100

  // 主材质 - 始终应用裁剪
  const mainMaterial = useMemo(() => {
    if (!materials.HZ3_Material_u1_v1) return null

    const material = materials.HZ3_Material_u1_v1.clone()

    // Slightly push the tail start inward to avoid coplanar overlap with the last colored slice.
    const tailBoundaryDistance = isMultiCutActive
      ? (() => {
          const lastLayer = sequentialCutLayers[sequentialCutLayers.length - 1]
          const lastLayerSpan = Math.max(lastLayer.endDistance - lastLayer.startDistance, 0)
          const tailBoundaryBias = Math.max(lastLayerSpan * 0.001, 1e-7)
          return lastLayer.endDistance + tailBoundaryBias
        })()
      : null

    const activePlane = isMultiCutActive
      ? createForwardPlane(cutNormal, tailBoundaryDistance!)
      : clippingPlane

    if (activePlane) {
      material.clippingPlanes = [activePlane]
      material.clipShadows = true
      material.needsUpdate = true
    }

    return material
  }, [materials.HZ3_Material_u1_v1, clippingPlane, isMultiCutActive, cutNormal, sequentialCutLayers])

  const showCutSection = showCutPlane && cutDepth > 0 && cutDepth < 100

  // Cut Face 模式：创建与裁剪面重合的大平面，最终由 stencil 裁成精确轮廓
  const capGeometry = useMemo(() => {
    if (!clippingPlane || mode !== 'cutFace' || !modelBounds) return null

    const box = modelBounds.box
    const diagonal = Math.sqrt(
      Math.pow(box.max.x - box.min.x, 2) +
      Math.pow(box.max.y - box.min.y, 2) +
      Math.pow(box.max.z - box.min.z, 2)
    )

    const geometry = new THREE.PlaneGeometry(diagonal * 2, diagonal * 2, 1, 1)

    const quaternion = new THREE.Quaternion()
    quaternion.setFromUnitVectors(
      new THREE.Vector3(0, 0, 1),
      clippingPlane.normal
    )
    geometry.applyQuaternion(quaternion)

    const position = clippingPlane.normal.clone().multiplyScalar(-clippingPlane.constant)
    geometry.translate(position.x, position.y, position.z)

    return geometry
  }, [clippingPlane, mode, modelBounds])

  const capMaterial = useMemo(() => {
    if (!clippingPlane || mode !== 'cutFace') return null

    const material = new THREE.MeshBasicMaterial({
      color: capColor,
      side: THREE.DoubleSide,
      transparent: false,
      opacity: 1.0,
      depthWrite: true,
      depthTest: true,
      fog: false,
      stencilWrite: true,
      stencilRef: 0,
      stencilFunc: THREE.NotEqualStencilFunc,
      stencilFail: THREE.ReplaceStencilOp,
      stencilZFail: THREE.ReplaceStencilOp,
      stencilZPass: THREE.ReplaceStencilOp,
    })

    material.needsUpdate = true
    return material
  }, [clippingPlane, capColor, mode])

  // 用前/后面双通道写 stencil，得到切割截面的精确掩码
  const stencilBackMaterial = useMemo(() => {
    if (!clippingPlane || mode !== 'cutFace') return null

    const material = new THREE.MeshBasicMaterial({
      side: THREE.BackSide,
      clippingPlanes: [clippingPlane],
      colorWrite: false,
      depthWrite: false,
      depthTest: false,
      stencilWrite: true,
      stencilFunc: THREE.AlwaysStencilFunc,
      stencilFail: THREE.KeepStencilOp,
      stencilZFail: THREE.KeepStencilOp,
      stencilZPass: THREE.IncrementWrapStencilOp,
    })

    material.needsUpdate = true
    return material
  }, [clippingPlane, mode])

  const stencilFrontMaterial = useMemo(() => {
    if (!clippingPlane || mode !== 'cutFace') return null

    const material = new THREE.MeshBasicMaterial({
      side: THREE.FrontSide,
      clippingPlanes: [clippingPlane],
      colorWrite: false,
      depthWrite: false,
      depthTest: false,
      stencilWrite: true,
      stencilFunc: THREE.AlwaysStencilFunc,
      stencilFail: THREE.KeepStencilOp,
      stencilZFail: THREE.KeepStencilOp,
      stencilZPass: THREE.DecrementWrapStencilOp,
    })

    material.needsUpdate = true
    return material
  }, [clippingPlane, mode])



  // Cut Body 模式：保留原材质颜色，仅叠加轻微高亮特效
  const cutBodyMaterial = useMemo(() => {
    if (!clippingPlane || mode !== 'cutBody') return null

    const reversePlane = new THREE.Plane(
      clippingPlane.normal.clone().negate(),
      -clippingPlane.constant
    )

    const material = materials.HZ3_Material_u1_v1.clone()
    material.side = THREE.DoubleSide
    material.transparent = true
    material.opacity = 0.5 //Cut Body被切割区域颜色透明度（越大透明度越高）
    material.clippingPlanes = [reversePlane]
    material.clipShadows = true

    // 轻微冷色发光，保留原本纹理与颜色层次
    material.emissive = new THREE.Color('#6fb7ff')//Cut Body被切割区域颜色
    material.emissiveIntensity = 0.12
    material.clearcoat = 0.5
    material.clearcoatRoughness = 0.35

    material.needsUpdate = true

    console.log(' 切割体材质:', {
      type: material.type,
      color: '#' + material.color.getHexString(),
      opacity: material.opacity,
      transparent: material.transparent,
      clippingPlanes: 'reverse',
      note: '保留原材质并叠加轻微高亮'
    })

    return material
  }, [clippingPlane, mode, materials.HZ3_Material_u1_v1])

  // Cut Body 截面填充：使用原材质颜色的提亮版，避免纯红色块
  const cutBodyCapMaterial = useMemo(() => {
    if (!clippingPlane || mode !== 'cutBody') return null

    // 创建反向裁剪平面（只保留截面部分）
    const reversePlane = new THREE.Plane(
      clippingPlane.normal.clone().negate(),
      -clippingPlane.constant
    )

    const sectionColor = materials.HZ3_Material_u1_v1.color.clone().lerp(new THREE.Color('#ffffff'), 1)

    const material = new THREE.MeshStandardMaterial({
      color: sectionColor,
      emissive: sectionColor.clone(),
      emissiveIntensity: 0.2,
      side: THREE.DoubleSide,
      transparent: false,
      opacity: 1.0,
      roughness: 0.35,
      metalness: 0.15,
      depthWrite: true,
      depthTest: true,
      fog: false,
      clippingPlanes: [reversePlane],
      clipShadows: true,
    })

    material.needsUpdate = true

    console.log(' 切割体截面材质:', {
      type: material.type,
      color: '#' + material.color.getHexString(),
      clippingPlanes: 'reverse (single plane)',
      side: 'DoubleSide',
      note: '原色提亮的截面填充'
    })

    return material
  }, [clippingPlane, mode, materials.HZ3_Material_u1_v1])

  const sequentialCutMaterials = useMemo(() => {
    if (mode !== 'cutBody' || sequentialCutLayers.length === 0) return [] as THREE.MeshPhysicalMaterial[]

    return sequentialCutLayers.map((layer) => {
      const material = materials.HZ3_Material_u1_v1.clone()
      const layerColor = new THREE.Color(layer.color)

      material.color = layerColor.clone()
      material.emissive = layerColor.clone()
      material.emissiveIntensity = 0.28
      material.side = THREE.DoubleSide
      material.transparent = true
      material.opacity = 0.72
      material.clearcoat = 0.5
      material.clearcoatRoughness = 0.35
      material.clippingPlanes = layer.clippingPlanes
      // Three.js clipping with this plane pair uses clipIntersection=false to keep slab interval.
      material.clipIntersection = false
      material.clipShadows = true
      // depthWrite = false 消除 Z-fighting（同几何体多层叠加时无需写深度）
      material.depthWrite = false
      material.needsUpdate = true

      return material
    })
  }, [mode, sequentialCutLayers, materials.HZ3_Material_u1_v1])

  if (!mainMaterial) return null

  return (
    <group dispose={null}>
      {/* 主模型 */}
      <mesh
        geometry={nodes.HZ3.geometry}
        material={mainMaterial}
        castShadow
        receiveShadow
      />

      {/* 原始 Cut Body：蓝色透明层 + 白色截面填充，统一受 showCutSection 控制 */}
      {mode === 'cutBody' && cutBodyMaterial && cutBodyCapMaterial && showCutSection && (
        <>
          <mesh
            geometry={nodes.HZ3.geometry}
            material={cutBodyMaterial}
            renderOrder={1}
          />

          {showCutBodyWireframe && (
            <mesh
              geometry={nodes.HZ3.geometry}
              renderOrder={2}
            >
              <meshBasicMaterial
                color="#ffffff"
                wireframe={true}
                transparent={true}
                opacity={0.5}
                clippingPlanes={[new THREE.Plane(
                  clippingPlane!.normal.clone().negate(),
                  -clippingPlane!.constant
                )]}
              />
            </mesh>
          )}

          <mesh
            geometry={nodes.HZ3.geometry}
            material={cutBodyCapMaterial}
            renderOrder={showCutBodyWireframe ? 3 : 2}
          />
        </>
      )}

      {/* 在 Cut Body 剩余部分（或完整模型）上继续切 N 刀 */}
      {isMultiCutActive && (
        <>
          {sequentialCutLayers.map((layer, index) => (
            <mesh
              key={`sequential-cut-${layer.index}`}
              geometry={nodes.HZ3.geometry}
              material={sequentialCutMaterials[index]}
              renderOrder={10 + index * 2}
            />
          ))}

          {showCutBodyWireframe && sequentialCutLayers.map((layer) => (
            <mesh
              key={`sequential-cut-wireframe-${layer.index}`}
              geometry={nodes.HZ3.geometry}
              renderOrder={11 + layer.index * 2}
            >
              <meshBasicMaterial
                color={layer.color}
                wireframe={true}
                transparent={true}
                opacity={0.32}
                clippingPlanes={layer.clippingPlanes}
                clipIntersection={false}
              />
            </mesh>
          ))}

        </>
      )}

      {/* 模式2: Cut Face - stencil 精确匹配截面边界 */}
      {mode === 'cutFace' && stencilBackMaterial && showCutSection && (
        <mesh
          geometry={nodes.HZ3.geometry}
          material={stencilBackMaterial}
          renderOrder={1}
        />
      )}

      {mode === 'cutFace' && stencilFrontMaterial && showCutSection && (
        <mesh
          geometry={nodes.HZ3.geometry}
          material={stencilFrontMaterial}
          renderOrder={2}
        />
      )}

      {mode === 'cutFace' && capGeometry && capMaterial && clippingPlane && showCutSection && (
        <mesh
          geometry={capGeometry}
          material={capMaterial}
          renderOrder={3}
          onAfterRender={(renderer: THREE.WebGLRenderer) => {
            renderer.clearStencil()
          }}
        />
      )}
    </group>
  )
}

useGLTF.preload('/Hohenzollern_Castle_optimized.glb')
